#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    long long n;
    cin >> m >> n;
    vector<vector<long long>> h(m, vector<long long>(n));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            cin >> h[i][j];
        }
    }

    typedef pair<long long, pair<int, int>> Cell;
    priority_queue<Cell, vector<Cell>, greater<Cell>> heap;
    vector<vector<char>> visited(m, vector<char>(n, 0));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                heap.push({h[i][j], {i, j}});
                visited[i][j] = 1;
            }
        }
    }
    long long water = 0;
    int di[4] = {1, -1, 0, 0}, dj[4] = {0, 0, 1, -1};
    while (!heap.empty()) {
        Cell top = heap.top();
        heap.pop();
        long long level = top.first;
        for (int d = 0; d < 4; d++) {
            int a = top.second.first + di[d], b = top.second.second + dj[d];
            if (a >= 0 && a < m && b >= 0 && b < n && !visited[a][b]) {
                visited[a][b] = 1;
                water += max(0LL, level - h[a][b]);
                heap.push({max(level, h[a][b]), {a, b}});
            }
        }
    }
    cout << water << "\n";

    return 0;
}

