import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long m = Long.parseLong(next());
        long n = Long.parseLong(next());
        long[][] h = new long[(int) m][(int) n];
        for (int i = 0; i < h.length; i++) {
            for (int j = 0; j < h[i].length; j++) {
                h[i][j] = Long.parseLong(next());
            }
        }

        PriorityQueue<long[]> heap = new PriorityQueue<>((p, q) -> Long.compare(p[0], q[0]));
        boolean[][] visited = new boolean[(int) m][(int) n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                    heap.add(new long[] {h[i][j], i, j});
                    visited[i][j] = true;
                }
            }
        }
        long water = 0;
        int[] di = {1, -1, 0, 0}, dj = {0, 0, 1, -1};
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            long level = top[0];
            for (int d = 0; d < 4; d++) {
                int a = (int) top[1] + di[d], b = (int) top[2] + dj[d];
                if (a >= 0 && a < m && b >= 0 && b < n && !visited[a][b]) {
                    visited[a][b] = true;
                    water += Math.max(0, level - h[a][b]);
                    heap.add(new long[] {Math.max(level, h[a][b]), a, b});
                }
            }
        }
        System.out.println(water);
    }
}
